const config = {
  // Test environment
  testEnvironment: 'node',

  // File extensions Jest will look for
  moduleFileExtensions: ['js', 'jsx', 'ts', 'tsx', 'json', 'node'],

  // Pattern to detect test files
  testMatch: [
    '**/__tests__/**/*.[jt]s?(x)',
    '**/?(*.)+(spec|test).[jt]s?(x)',
  ],

  // Paths to ignore when searching for tests
  testPathIgnorePatterns: [
    '/node_modules/',
    '/dist/',
    '/build/',
  ],

  // Transform configuration (uncomment if using Babel or TypeScript)
  // transform: {
  //   '^.+\\.[jt]sx?$': 'babel-jest',   // Babel
  //   '^.+\\.tsx?$': 'ts-jest',          // TypeScript
  // },

  // Module name mapper for path aliases (adjust to your project)
  // moduleNameMapper: {
  //   '^@/(.*)$': '<rootDir>/src/$1',
  // },

  // Coverage configuration
  collectCoverage: false, // Set to true to always collect coverage
  collectCoverageFrom: [
    'src/**/*.[jt]s?(x)',
    '!src/**/*.d.ts',
    '!src/**/index.[jt]s',
  ],
  coverageDirectory: 'coverage',
  coverageReporters: ['text', 'lcov', 'clover'],
  coverageThresholds: {
    // global: {
