/**
 * jest.globalSetup.js
 *
 * Runs ONCE before all test suites.
 * Use this for expensive one-time setup: starting servers, seeding databases, etc.
 * Note: This file runs in its own context — no access to globals set here from tests.
 *       Use globalTeardown for cleanup after all suites finish.
 */

module.exports = async function globalSetup() {
  // Example: set an environment variable available to all tests
  process.env.NODE_ENV = 'test';

  // Example: start a test database or server
  // global.__SERVER__ = await startServer();

  console.log('\n[globalSetup] Test environment initialized.');
};
